 bindings.append({**op,'request_contract':None if not op['request_type'] else 'urn:pulse:contracts:v3#/$defs/'+op['request_type'],'response_contract':'urn:pulse:contracts:v3#/$defs/'+op['operation_id']+'Response','event_schema_version':VERSION if op['events'] else None,'cache_and_consistency':('Frozen analysis core is cached by release_id/scope/projection_version. Its projection_hash excludes dynamic quote_overlay/actionability_id and ResponseMeta.generated_at; resolve and cache overlays independently by their own snapshot/version/freshness policy.' if op['operation_id']=='getStockWorkspace' else cache_policies[op['consistency']]),'implementation_status':'contract_seed','mutations':'none' if op['method']=='GET' else 'Application service owns short transaction, version/idempotency checks, canonical writes and outbox; API must not duplicate logic.'})
